import java.util.*;

public class Main {
    static class Record {
        String ip;
        int weight;
        int latencyMs;
        boolean healthy;

        Record(String ip, int weight, int latencyMs, boolean healthy) {
            this.ip = ip;
            this.weight = weight;
            this.latencyMs = latencyMs;
            this.healthy = healthy;
        }
    }

    static String roundRobin(List<Record> records, int requestIndex) {
        return records.get(requestIndex % records.size()).ip;
    }

    static String weighted(List<Record> records, int roll) {
        int cumulative = 0;
        for (Record r : records) {
            cumulative += r.weight;
            if (roll < cumulative) return r.ip;
        }
        return records.get(records.size() - 1).ip;
    }

    static String latencyBased(List<Record> records) {
        Record best = records.get(0);
        for (Record r : records) {
            if (r.latencyMs < best.latencyMs) best = r;
        }
        return best.ip;
    }

    static String failover(Record primary, Record secondary) {
        return primary.healthy ? primary.ip : secondary.ip;
    }

    public static void main(String[] args) {
        List<Record> pool = Arrays.asList(
            new Record("54.12.10.1", 0, 0, true),
            new Record("54.12.10.2", 0, 0, true),
            new Record("54.12.10.3", 0, 0, true)
        );
        StringBuilder rr = new StringBuilder();
        for (int i = 0; i < 6; i++) rr.append(roundRobin(pool, i)).append(i < 5 ? ", " : "");
        System.out.println("Round robin over 6 requests: " + rr);

        List<Record> weightedPool = Arrays.asList(
            new Record("v1", 80, 0, true),
            new Record("v2", 20, 0, true)
        );
        Map<String, Integer> counts = new LinkedHashMap<>();
        counts.put("v1", 0);
        counts.put("v2", 0);
        for (int roll = 0; roll < 100; roll += 10) {
            String chosen = weighted(weightedPool, roll);
            counts.put(chosen, counts.get(chosen) + 1);
        }
        System.out.println("Weighted routing over 10 sampled rolls: " + counts);

        List<Record> regions = Arrays.asList(
            new Record("us-east-1", 0, 280, true),
            new Record("ap-south-1", 0, 12, true)
        );
        System.out.println("Latency-based routing picks: " + latencyBased(regions));

        Record primary = new Record("54.12.10.1", 0, 0, true);
        Record secondary = new Record("54.12.10.2", 0, 0, true);
        System.out.println("Failover while primary healthy: " + failover(primary, secondary));
        primary.healthy = false;
        System.out.println("Failover after primary fails health checks: " + failover(primary, secondary));
    }
}

