class Record:
    def __init__(self, ip, weight=0, latency_ms=0, healthy=True):
        self.ip = ip
        self.weight = weight
        self.latency_ms = latency_ms
        self.healthy = healthy


def round_robin(records, request_index):
    return records[request_index % len(records)].ip


def weighted(records, roll):
    cumulative = 0
    for r in records:
        cumulative += r.weight
        if roll < cumulative:
            return r.ip
    return records[-1].ip


def latency_based(records):
    best = records[0]
    for r in records:
        if r.latency_ms < best.latency_ms:
            best = r
    return best.ip


def failover(primary, secondary):
    return primary.ip if primary.healthy else secondary.ip


def main():
    pool = [Record("54.12.10.1"), Record("54.12.10.2"), Record("54.12.10.3")]
    rr = [round_robin(pool, i) for i in range(6)]
    print(f"Round robin over 6 requests: {', '.join(rr)}")

    weighted_pool = [Record("v1", weight=80), Record("v2", weight=20)]
    counts = {"v1": 0, "v2": 0}
    for roll in range(0, 100, 10):
        chosen = weighted(weighted_pool, roll)
        counts[chosen] += 1
    print(f"Weighted routing over 10 sampled rolls: {counts}")

    regions = [Record("us-east-1", latency_ms=280), Record("ap-south-1", latency_ms=12)]
    print(f"Latency-based routing picks: {latency_based(regions)}")

    primary = Record("54.12.10.1")
    secondary = Record("54.12.10.2")
    print(f"Failover while primary healthy: {failover(primary, secondary)}")
    primary.healthy = False
    print(f"Failover after primary fails health checks: {failover(primary, secondary)}")


if __name__ == "__main__":
    main()

