#include <iostream>
#include <string>
#include <vector>
#include <map>
using namespace std;

struct Record {
    string ip;
    int weight;
    int latencyMs;
    bool healthy;
    Record(string ip, int weight = 0, int latencyMs = 0, bool healthy = true)
        : ip(ip), weight(weight), latencyMs(latencyMs), healthy(healthy) {}
};

string roundRobin(vector<Record>& records, int requestIndex) {
    return records[requestIndex % records.size()].ip;
}

string weighted(vector<Record>& records, int roll) {
    int cumulative = 0;
    for (auto& r : records) {
        cumulative += r.weight;
        if (roll < cumulative) return r.ip;
    }
    return records.back().ip;
}

string latencyBased(vector<Record>& records) {
    Record best = records[0];
    for (auto& r : records) {
        if (r.latencyMs < best.latencyMs) best = r;
    }
    return best.ip;
}

string failover(Record& primary, Record& secondary) {
    return primary.healthy ? primary.ip : secondary.ip;
}

int main() {
    vector<Record> pool = {Record("54.12.10.1"), Record("54.12.10.2"), Record("54.12.10.3")};
    cout << "Round robin over 6 requests: ";
    for (int i = 0; i < 6; i++) {
        cout << roundRobin(pool, i);
        if (i < 5) cout << ", ";
    }
    cout << endl;

    vector<Record> weightedPool = {Record("v1", 80), Record("v2", 20)};
    map<string, int> counts = {{"v1", 0}, {"v2", 0}};
    for (int roll = 0; roll < 100; roll += 10) {
        string chosen = weighted(weightedPool, roll);
        counts[chosen]++;
    }
    cout << "Weighted routing over 10 sampled rolls: {v1=" << counts["v1"] << ", v2=" << counts["v2"] << "}" << endl;

    vector<Record> regions = {Record("us-east-1", 0, 280), Record("ap-south-1", 0, 12)};
    cout << "Latency-based routing picks: " << latencyBased(regions) << endl;

    Record primary("54.12.10.1");
    Record secondary("54.12.10.2");
    cout << "Failover while primary healthy: " << failover(primary, secondary) << endl;
    primary.healthy = false;
    cout << "Failover after primary fails health checks: " << failover(primary, secondary) << endl;

    return 0;
}
